import re
import unicodedata


def run(text):
    text = "".join(c for c in unicodedata.normalize("NFKD", text) if not unicodedata.combining(c))
    text = text.replace("&", " and ")
    out = []
    for ch in text.lower():
        if ch == " ":
            out.append("-")
        elif ch.isascii() and (ch.isalnum() or ch == "-"):
            out.append(ch)
    return re.sub("-+", "-", "".join(out)).strip("-")
